# -*- coding: utf-8 -*-
"""桌面 v2 槽位会话的 handoff、Token 与里程碑证明。"""
from __future__ import annotations

import base64
import hashlib
import hmac
import json
import os
import re
import secrets
import threading
import time
from dataclasses import dataclass
from typing import Awaitable, Callable

_OPERATION_ID_RE = re.compile(r"[0-9a-f]{32}")
_SESSION_ID_RE = re.compile(r"[0-9a-f]{32}")
_DIGEST_RE = re.compile(r"[0-9a-f]{64}")
_OPAQUE_RE = re.compile(r"[A-Za-z0-9_-]{1,128}")
_HANDOFF_CODE_RE = re.compile(r"[A-Za-z0-9_-]{32,128}")
_PURPOSES = frozenset(
    {"initial_active", "candidate", "rollback_active"}
)
_MILESTONES = frozenset(
    {
        "navigation_committed",
        "shell_ready",
        "interactive",
        "old_retired",
    }
)
_MAX_HANDOFF_TTL_SECONDS = 30.0
# 开机初期 NTP 校时可能让 shell 与 backend 的时间基准瞬间错位；register 仅
# 持 handshake secret 的 shell 可调用，对小幅时钟跳变做钳制而非拒绝，
# 避免冷启动 handoff 全部失效导致登录循环。
_HANDOFF_CLOCK_SKEW_GRACE_SECONDS = 300.0
_TOKEN_KIND = "desktop_v2"
_DESKTOP_SESSION_TTL_SECONDS = 900
_PREVIEW_TICKET_KIND = "desktop_file_preview_v1"
_PREVIEW_SESSION_TOKEN_KIND = "desktop_file_preview_session_v1"
_PROOF_KIND = "desktop_milestone_proof"
_MAX_PREVIEW_TICKET_TTL_SECONDS = 900


class DesktopSecurityError(RuntimeError):
    """桌面槽位安全状态的基础异常。"""


class DesktopHandoffInvalid(DesktopSecurityError):
    """handoff 请求字段或 TTL 无效。"""


class DesktopHandoffConflict(DesktopSecurityError):
    """handoff 与槽位水位或现有 pending 冲突。"""


class DesktopHandoffUnauthorized(DesktopSecurityError):
    """handoff code 未知、过期、不匹配或已重放。"""


class DesktopSsoUnavailable(DesktopSecurityError):
    """有效 handoff 暂时无法取得可用 SSO 身份。"""


class DesktopTokenSigningError(DesktopSecurityError):
    """Token 签发失败，pending 必须保留。"""


@dataclass(frozen=True)
class DesktopSlotSecurityConfig:
    """一个桌面 v2 后端槽位不可变的安全配置。"""

    initial_operation_id: str
    slot_generation: int
    audience: str
    profile_namespace: str
    signing_key: str
    handshake_secret: str
    initial_purpose: str = "candidate"

    @classmethod
    def from_env(cls) -> "DesktopSlotSecurityConfig | None":
        """严格读取 v2 槽位环境；不完整时关闭 v2 而不是半启用。"""
        if os.environ.get("EAZYBOT_DESKTOP_PROTOCOL", "").strip() != "v2":
            return None
        operation_id = os.environ.get(
            "EAZYBOT_DESKTOP_INITIAL_OPERATION_ID",
            "",
        ).strip().lower()
        generation_raw = os.environ.get(
            "EAZYBOT_DESKTOP_SLOT_GENERATION",
            "",
        ).strip()
        audience = os.environ.get(
            "EAZYBOT_DESKTOP_SLOT_AUDIENCE",
            "",
        ).strip()
        namespace = os.environ.get(
            "EAZYBOT_DESKTOP_PROFILE_NAMESPACE",
            "",
        ).strip()
        signing_key = os.environ.get(
            "EAZYBOT_DESKTOP_SESSION_SIGNING_KEY",
            "",
        ).strip()
        handshake_secret = os.environ.get(
            "EAZYBOT_SHELL_HANDSHAKE_SECRET",
            "",
        ).strip()
        initial_purpose = os.environ.get(
            "EAZYBOT_DESKTOP_INITIAL_PURPOSE",
            "candidate",
        ).strip()
        try:
            generation = int(generation_raw)
        except ValueError:
            return None
        if (
            _OPERATION_ID_RE.fullmatch(operation_id) is None
            or generation <= 0
            or _OPAQUE_RE.fullmatch(audience) is None
            or _OPAQUE_RE.fullmatch(namespace) is None
            or len(namespace) < 16
            or len(signing_key) < 32
            or len(handshake_secret) < 32
            or initial_purpose not in {"initial_active", "candidate"}
        ):
            return None
        return cls(
            initial_operation_id=operation_id,
            slot_generation=generation,
            audience=audience,
            profile_namespace=namespace,
            signing_key=signing_key,
            handshake_secret=handshake_secret,
            initial_purpose=initial_purpose,
        )


@dataclass(frozen=True)
class HandoffContextStamp:
    """handoff 与后续 Token 必须共同绑定的操作上下文。"""

    operation_id: str
    generation: int
    slot_generation: int
    purpose: str


@dataclass(frozen=True)
class HandoffBinding:
    """Shell 注册到单个后端槽位的一次性 handoff。"""

    session_id: str
    context: HandoffContextStamp
    digest: str
    expires_at: float
    monotonic_deadline: float
    version: int


@dataclass(frozen=True)
class DesktopSessionBinding:
    """当前槽位唯一有效的 Console 会话绑定。"""

    user_id: str
    session_id: str
    operation_id: str
    audience: str
    generation: int
    slot_generation: int
    profile_namespace: str
    purpose: str


@dataclass(frozen=True)
class DesktopTokenClaims:
    """已验签且与 current binding 完全匹配的 Token claims。"""

    user_id: str
    session_id: str
    operation_id: str
    audience: str
    generation: int
    slot_generation: int
    profile_namespace: str
    purpose: str
    token_kind: str
    issued_at: int
    expires_at: int
    token_id: str


@dataclass(frozen=True)
class MilestoneProofClaims:
    """Shell 可验证并交给 Coordinator 消费的短效里程碑证明。"""

    session_id: str
    operation_id: str
    audience: str
    generation: int
    slot_generation: int
    profile_namespace: str
    purpose: str
    milestone: str
    nonce: str
    issued_at: int
    expires_at: int


@dataclass(frozen=True)
class DesktopRedeemResult:
    """一次成功兑换后的会话与短效 Token。"""

    access_token: str
    preview_token: str
    expires_in: int
    binding: DesktopSessionBinding


@dataclass(frozen=True)
class _RedeemReservation:
    reservation_id: str
    digest: str
    binding_version: int
    monotonic_deadline: float


def _b64encode(value: bytes) -> str:
    return base64.urlsafe_b64encode(value).decode("ascii").rstrip("=")


def _b64decode(value: str) -> bytes:
    padding = "=" * (-len(value) % 4)
    return base64.urlsafe_b64decode(value + padding)


def _sign_payload(payload: dict, signing_key: str) -> str:
    body = json.dumps(
        payload,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("utf-8")
    encoded = _b64encode(body)
    signature = hmac.new(
        signing_key.encode("utf-8"),
        encoded.encode("ascii"),
        hashlib.sha256,
    ).hexdigest()
    return f"{encoded}.{signature}"


def _verify_payload(token: str, signing_key: str) -> dict | None:
    try:
        encoded, signature = token.split(".", 1)
        expected = hmac.new(
            signing_key.encode("utf-8"),
            encoded.encode("ascii"),
            hashlib.sha256,
        ).hexdigest()
        if not hmac.compare_digest(signature, expected):
            return None
        payload = json.loads(_b64decode(encoded))
    except (ValueError, TypeError, json.JSONDecodeError):
        return None
    return payload if isinstance(payload, dict) else None


def create_desktop_token(
    user_id: str,
    *,
    signing_key: str,
    session_id: str,
    operation_id: str,
    audience: str,
    generation: int,
    slot_generation: int,
    profile_namespace: str,
    purpose: str,
    expires_seconds: int = 900,
) -> str:
    """签发只对一个槽位 current session 有效的短效 Token。"""
    now = int(time.time())
    expires = max(1, min(int(expires_seconds), 900))
    return _sign_payload(
        {
            "sub": user_id,
            "session_id": session_id,
            "operation_id": operation_id,
            "aud": audience,
            "generation": generation,
            "slot_generation": slot_generation,
            "profile_namespace": profile_namespace,
            "purpose": purpose,
            "token_kind": _TOKEN_KIND,
            "iat": now,
            "exp": now + expires,
            "jti": secrets.token_hex(16),
        },
        signing_key,
    )


def decode_desktop_token(
    token: str,
    *,
    signing_key: str,
    expected: DesktopSessionBinding,
    skip_expiry: bool = False,
) -> DesktopTokenClaims | None:
    """验签并逐字段比对 current binding，任何不匹配都失败。

    ``skip_expiry``：桌面端长时间不动后系统休眠导致 token 过期，
    但 SSO 会话可能仍有效。对 ``/api/sso/desktop-token/refresh``
    端点跳过 ``exp`` 检查——token 结构正确 + claims 与 current
    session 匹配即允许换新 token，不需走完整 SSO 重登。安全面
    不降级：``_claims_match_current_locked()`` 仍会逐字段比对
    generation / slot_generation / profile_namespace 等。
    """
    payload = _verify_payload(token, signing_key)
    if payload is None:
        return None
    try:
        claims = DesktopTokenClaims(
            user_id=payload["sub"],
            session_id=payload["session_id"],
            operation_id=payload["operation_id"],
            audience=payload["aud"],
            generation=payload["generation"],
            slot_generation=payload["slot_generation"],
            profile_namespace=payload["profile_namespace"],
            purpose=payload["purpose"],
            token_kind=payload["token_kind"],
            issued_at=payload["iat"],
            expires_at=payload["exp"],
            token_id=payload["jti"],
        )
    except (KeyError, TypeError):
        return None
    if (
        not isinstance(claims.user_id, str)
        or not isinstance(claims.generation, int)
        or isinstance(claims.generation, bool)
        or not isinstance(claims.slot_generation, int)
        or isinstance(claims.slot_generation, bool)
        or not isinstance(claims.issued_at, int)
        or not isinstance(claims.expires_at, int)
        or claims.token_kind != _TOKEN_KIND
        or claims.user_id != expected.user_id
        or claims.session_id != expected.session_id
        or claims.operation_id != expected.operation_id
        or claims.audience != expected.audience
        or claims.generation != expected.generation
        or claims.slot_generation != expected.slot_generation
        or claims.profile_namespace != expected.profile_namespace
        or claims.purpose != expected.purpose
    ):
        return None
    if not skip_expiry and claims.expires_at < time.time():
        return None
    return claims


def create_desktop_preview_ticket(
    binding: DesktopSessionBinding,
    *,
    filepath: str,
    signing_key: str,
    expires_seconds: int = _MAX_PREVIEW_TICKET_TTL_SECONDS,
) -> str:
    """签发只能读取一个文件的短时预览票据。

    原生媒体标签和第三方文档 viewer 不能注入 Authorization header，因而
    只能把此票据放进 URL。它与 desktop bearer 使用不同 token_kind，并额外
    绑定当前槽位会话和归一化后的文件路径，不能作为通用 API 凭据使用。
    """
    if not filepath:
        raise ValueError("preview_filepath_empty")
    now = int(time.time())
    expires = max(
        1,
        min(int(expires_seconds), _MAX_PREVIEW_TICKET_TTL_SECONDS),
    )
    return _sign_payload(
        {
            "sub": binding.user_id,
            "session_id": binding.session_id,
            "operation_id": binding.operation_id,
            "aud": binding.audience,
            "generation": binding.generation,
            "slot_generation": binding.slot_generation,
            "profile_namespace": binding.profile_namespace,
            "purpose": binding.purpose,
            "path": filepath,
            "token_kind": _PREVIEW_TICKET_KIND,
            "iat": now,
            "exp": now + expires,
            "jti": secrets.token_hex(16),
        },
        signing_key,
    )


def decode_desktop_preview_ticket(
    ticket: str,
    *,
    filepath: str,
    signing_key: str,
    expected: DesktopSessionBinding,
) -> bool:
    """验证预览票据的类型、TTL、会话和文件路径，不能验成 bearer。"""
    payload = _verify_payload(ticket, signing_key)
    if payload is None or payload.get("token_kind") != _PREVIEW_TICKET_KIND:
        return False
    try:
        issued_at = payload["iat"]
        expires_at = payload["exp"]
        token_id = payload["jti"]
        ticket_path = payload["path"]
    except KeyError:
        return False
    if (
        not isinstance(issued_at, int)
        or isinstance(issued_at, bool)
        or not isinstance(expires_at, int)
        or isinstance(expires_at, bool)
        or expires_at < time.time()
        or not isinstance(token_id, str)
        or _SESSION_ID_RE.fullmatch(token_id) is None
        or not isinstance(ticket_path, str)
        or ticket_path != filepath
        or payload.get("sub") != expected.user_id
        or payload.get("session_id") != expected.session_id
        or payload.get("operation_id") != expected.operation_id
        or payload.get("aud") != expected.audience
        or payload.get("generation") != expected.generation
        or payload.get("slot_generation") != expected.slot_generation
        or payload.get("profile_namespace")
        != expected.profile_namespace
        or payload.get("purpose") != expected.purpose
    ):
        return False
    return True


def create_desktop_preview_session_token(
    binding: DesktopSessionBinding,
    *,
    signing_key: str,
    expires_seconds: int = 900,
) -> str:
    """签发仅能访问 preview 路由的 session-bound 短效能力票据。

    聊天气泡的原生图片/音视频标签无法等待异步换取逐文件票据，因此它们使用
    此票据。它仍与 desktop bearer 有独立 token_kind，只能在 GET/HEAD preview
    路由被认证，绝不能调用其他 API。
    """
    now = int(time.time())
    expires = max(1, min(int(expires_seconds), 900))
    return _sign_payload(
        {
            "sub": binding.user_id,
            "session_id": binding.session_id,
            "operation_id": binding.operation_id,
            "aud": binding.audience,
            "generation": binding.generation,
            "slot_generation": binding.slot_generation,
            "profile_namespace": binding.profile_namespace,
            "purpose": binding.purpose,
            "token_kind": _PREVIEW_SESSION_TOKEN_KIND,
            "iat": now,
            "exp": now + expires,
            "jti": secrets.token_hex(16),
        },
        signing_key,
    )


def decode_desktop_preview_session_token(
    token: str,
    *,
    signing_key: str,
    expected: DesktopSessionBinding,
) -> DesktopTokenClaims | None:
    """验签 session-bound preview capability；返回 claims 供中间件设置用户。"""
    payload = _verify_payload(token, signing_key)
    if payload is None:
        return None
    try:
        claims = DesktopTokenClaims(
            user_id=payload["sub"],
            session_id=payload["session_id"],
            operation_id=payload["operation_id"],
            audience=payload["aud"],
            generation=payload["generation"],
            slot_generation=payload["slot_generation"],
            profile_namespace=payload["profile_namespace"],
            purpose=payload["purpose"],
            token_kind=payload["token_kind"],
            issued_at=payload["iat"],
            expires_at=payload["exp"],
            token_id=payload["jti"],
        )
    except (KeyError, TypeError):
        return None
    if (
        not isinstance(claims.user_id, str)
        or not isinstance(claims.generation, int)
        or isinstance(claims.generation, bool)
        or not isinstance(claims.slot_generation, int)
        or isinstance(claims.slot_generation, bool)
        or not isinstance(claims.issued_at, int)
        or not isinstance(claims.expires_at, int)
        or claims.expires_at < time.time()
        or claims.token_kind != _PREVIEW_SESSION_TOKEN_KIND
        or claims.user_id != expected.user_id
        or claims.session_id != expected.session_id
        or claims.operation_id != expected.operation_id
        or claims.audience != expected.audience
        or claims.generation != expected.generation
        or claims.slot_generation != expected.slot_generation
        or claims.profile_namespace != expected.profile_namespace
        or claims.purpose != expected.purpose
    ):
        return None
    return claims


def create_milestone_proof(
    binding: DesktopSessionBinding,
    *,
    milestone: str,
    handshake_secret: str,
    expires_seconds: int = 15,
) -> str:
    """从 current binding 派生不可跨槽复用的短效 proof。"""
    if milestone not in _MILESTONES:
        raise DesktopHandoffInvalid("milestone_invalid")
    now = int(time.time())
    expires = max(1, min(int(expires_seconds), 15))
    return _sign_payload(
        {
            "session_id": binding.session_id,
            "operation_id": binding.operation_id,
            "aud": binding.audience,
            "generation": binding.generation,
            "slot_generation": binding.slot_generation,
            "profile_namespace": binding.profile_namespace,
            "purpose": binding.purpose,
            "milestone": milestone,
            "nonce": secrets.token_hex(16),
            "token_kind": _PROOF_KIND,
            "iat": now,
            "exp": now + expires,
        },
        handshake_secret,
    )


def decode_milestone_proof(
    proof: str,
    *,
    handshake_secret: str,
) -> MilestoneProofClaims | None:
    """验证里程碑 proof 的签名、类型、TTL 与字段形状。"""
    payload = _verify_payload(proof, handshake_secret)
    if payload is None or payload.get("token_kind") != _PROOF_KIND:
        return None
    try:
        claims = MilestoneProofClaims(
            session_id=payload["session_id"],
            operation_id=payload["operation_id"],
            audience=payload["aud"],
            generation=payload["generation"],
            slot_generation=payload["slot_generation"],
            profile_namespace=payload["profile_namespace"],
            purpose=payload["purpose"],
            milestone=payload["milestone"],
            nonce=payload["nonce"],
            issued_at=payload["iat"],
            expires_at=payload["exp"],
        )
    except (KeyError, TypeError):
        return None
    if (
        not isinstance(claims.generation, int)
        or isinstance(claims.generation, bool)
        or not isinstance(claims.slot_generation, int)
        or isinstance(claims.slot_generation, bool)
        or not isinstance(claims.issued_at, int)
        or not isinstance(claims.expires_at, int)
        or claims.expires_at < time.time()
        or claims.milestone not in _MILESTONES
        or _SESSION_ID_RE.fullmatch(claims.session_id) is None
        or _OPERATION_ID_RE.fullmatch(claims.operation_id) is None
        or _SESSION_ID_RE.fullmatch(claims.nonce) is None
    ):
        return None
    return claims


class DesktopSecurityState:
    """单个后端槽位的全部 handoff 与 current session 状态。"""

    def __init__(
        self,
        config: DesktopSlotSecurityConfig,
        *,
        wall_clock: Callable[[], float] = time.time,
        monotonic_clock: Callable[[], float] = time.monotonic,
        token_factory: Callable[..., str] = create_desktop_token,
    ) -> None:
        self.config = config
        self._wall_clock = wall_clock
        self._monotonic_clock = monotonic_clock
        self._token_factory = token_factory
        self._lock = threading.RLock()
        self._pending: HandoffBinding | None = None
        self._reservation: _RedeemReservation | None = None
        self._consumed: dict[str, float] = {}
        self._seen_session_ids: set[str] = set()
        self._current: DesktopSessionBinding | None = None
        self._high_watermark = HandoffContextStamp(
            operation_id=config.initial_operation_id,
            generation=config.slot_generation,
            slot_generation=config.slot_generation,
            purpose=config.initial_purpose,
        )
        self._version = 0

    @property
    def current_session(self) -> DesktopSessionBinding | None:
        with self._lock:
            return self._current

    def _cleanup_locked(self) -> None:
        now = self._monotonic_clock()
        self._consumed = {
            digest: deadline
            for digest, deadline in self._consumed.items()
            if deadline > now
        }
        if (
            self._pending is not None
            and self._pending.monotonic_deadline <= now
        ):
            self._pending = None
        if (
            self._reservation is not None
            and self._reservation.monotonic_deadline <= now
        ):
            self._reservation = None

    @staticmethod
    def _validate_context(context: HandoffContextStamp) -> None:
        if (
            _OPERATION_ID_RE.fullmatch(context.operation_id) is None
            or not isinstance(context.generation, int)
            or isinstance(context.generation, bool)
            or context.generation <= 0
            or not isinstance(context.slot_generation, int)
            or isinstance(context.slot_generation, bool)
            or context.slot_generation <= 0
            or context.purpose not in _PURPOSES
        ):
            raise DesktopHandoffInvalid("context_invalid")

    def register(
        self,
        *,
        session_id: str,
        operation_id: str,
        generation: int,
        slot_generation: int,
        purpose: str,
        digest: str,
        expires_at: float,
    ) -> None:
        """原子注册一次性 handoff；相同 payload 重试幂等。"""
        operation_id = operation_id.lower()
        context = HandoffContextStamp(
            operation_id=operation_id,
            generation=generation,
            slot_generation=slot_generation,
            purpose=purpose,
        )
        self._validate_context(context)
        now_wall = self._wall_clock()
        if (
            isinstance(expires_at, (int, float))
            and not isinstance(expires_at, bool)
        ):
            if 0 < now_wall - expires_at <= _HANDOFF_CLOCK_SKEW_GRACE_SECONDS:
                # 时钟后跳：expires_at 落入"过去"，按满额 TTL 重新起算
                expires_at = now_wall + _MAX_HANDOFF_TTL_SECONDS
            elif (
                expires_at - now_wall > _MAX_HANDOFF_TTL_SECONDS
                and expires_at - now_wall
                <= _MAX_HANDOFF_TTL_SECONDS + _HANDOFF_CLOCK_SKEW_GRACE_SECONDS
            ):
                # 时钟前跳：expires_at 超出上限但差距在宽限内，钳到上限
                expires_at = now_wall + _MAX_HANDOFF_TTL_SECONDS
        if (
            _SESSION_ID_RE.fullmatch(session_id) is None
            or _DIGEST_RE.fullmatch(digest) is None
            or not isinstance(expires_at, (int, float))
            or isinstance(expires_at, bool)
            or expires_at <= now_wall
            or expires_at - now_wall > _MAX_HANDOFF_TTL_SECONDS
        ):
            raise DesktopHandoffInvalid("registration_invalid")
        if slot_generation != self.config.slot_generation:
            raise DesktopHandoffConflict("slot_generation_stale")
        if purpose in {"initial_active", "candidate"}:
            if (
                purpose != self.config.initial_purpose
                or generation != self.config.slot_generation
                or operation_id != self.config.initial_operation_id
            ):
                raise DesktopHandoffConflict("initial_context_stale")
        if purpose == "rollback_active" and (
            generation <= self.config.slot_generation
        ):
            raise DesktopHandoffConflict("rollback_generation_stale")

        monotonic_deadline = self._monotonic_clock() + (
            expires_at - now_wall
        )
        with self._lock:
            self._cleanup_locked()
            pending = self._pending
            if pending is not None:
                identical = (
                    pending.session_id == session_id
                    and pending.context == context
                    and pending.digest == digest
                    and pending.expires_at == expires_at
                )
                if identical:
                    return
                raise DesktopHandoffConflict("pending_conflict")
            if digest in self._consumed:
                raise DesktopHandoffConflict("digest_consumed")
            if session_id in self._seen_session_ids:
                raise DesktopHandoffConflict("session_id_reused")

            watermark = self._high_watermark
            if context.generation < watermark.generation:
                raise DesktopHandoffConflict("generation_stale")
            if (
                context.generation == watermark.generation
                and context != watermark
            ):
                raise DesktopHandoffConflict("context_conflict")

            self._version += 1
            self._pending = HandoffBinding(
                session_id=session_id,
                context=context,
                digest=digest,
                expires_at=float(expires_at),
                monotonic_deadline=monotonic_deadline,
                version=self._version,
            )
            self._seen_session_ids.add(session_id)
            if context.generation > watermark.generation:
                self._high_watermark = context

    def _begin_redeem(self, raw_code: str) -> _RedeemReservation:
        if _HANDOFF_CODE_RE.fullmatch(raw_code) is None:
            raise DesktopHandoffUnauthorized("handoff_invalid")
        digest = hashlib.sha256(raw_code.encode("utf-8")).hexdigest()
        with self._lock:
            self._cleanup_locked()
            pending = self._pending
            now = self._monotonic_clock()
            if (
                pending is None
                or pending.digest != digest
                or pending.monotonic_deadline <= now
                or digest in self._consumed
                or self._reservation is not None
            ):
                raise DesktopHandoffUnauthorized("handoff_invalid")
            reservation = _RedeemReservation(
                reservation_id=secrets.token_hex(16),
                digest=digest,
                binding_version=pending.version,
                monotonic_deadline=min(
                    pending.monotonic_deadline,
                    now + 10.0,
                ),
            )
            self._reservation = reservation
            return reservation

    def _release_reservation(self, reservation_id: str) -> None:
        with self._lock:
            if (
                self._reservation is not None
                and self._reservation.reservation_id == reservation_id
            ):
                self._reservation = None

    def _finish_redeem(
        self,
        reservation: _RedeemReservation,
        user_id: str,
    ) -> DesktopRedeemResult:
        with self._lock:
            self._cleanup_locked()
            pending = self._pending
            current_reservation = self._reservation
            if (
                pending is None
                or current_reservation != reservation
                or pending.version != reservation.binding_version
                or pending.digest != reservation.digest
                or pending.monotonic_deadline <= self._monotonic_clock()
                or pending.context != self._high_watermark
            ):
                raise DesktopHandoffUnauthorized("handoff_invalid")
            binding = DesktopSessionBinding(
                user_id=user_id,
                session_id=pending.session_id,
                operation_id=pending.context.operation_id,
                audience=self.config.audience,
                generation=pending.context.generation,
                slot_generation=pending.context.slot_generation,
                profile_namespace=self.config.profile_namespace,
                purpose=pending.context.purpose,
            )
            try:
                token = self._token_factory(
                    user_id,
                    signing_key=self.config.signing_key,
                    session_id=binding.session_id,
                    operation_id=binding.operation_id,
                    audience=binding.audience,
                    generation=binding.generation,
                    slot_generation=binding.slot_generation,
                    profile_namespace=binding.profile_namespace,
                    purpose=binding.purpose,
                    expires_seconds=_DESKTOP_SESSION_TTL_SECONDS,
                )
            except Exception as exc:
                raise DesktopTokenSigningError(
                    "token_signing_failed"
                ) from exc
            self._consumed[pending.digest] = pending.monotonic_deadline
            self._pending = None
            self._reservation = None
            self._current = binding
            preview_token = create_desktop_preview_session_token(
                binding,
                signing_key=self.config.signing_key,
            )
            return DesktopRedeemResult(
                token,
                preview_token,
                _DESKTOP_SESSION_TTL_SECONDS,
                binding,
            )

    async def redeem(
        self,
        raw_code: str,
        resolve_user: Callable[[], Awaitable[str | None]],
    ) -> DesktopRedeemResult:
        """三段式兑换；SSO 调用在锁外且失败不消费 pending。"""
        reservation = self._begin_redeem(raw_code)
        try:
            user_id = await resolve_user()
            if not user_id:
                raise DesktopSsoUnavailable("sso_token_invalid")
            return self._finish_redeem(reservation, user_id)
        finally:
            self._release_reservation(reservation.reservation_id)

    def authenticate(self, token: str) -> DesktopTokenClaims | None:
        """只接受与此刻 current session 完全相同的 bearer。"""
        with self._lock:
            current = self._current
            if current is None:
                return None
            return decode_desktop_token(
                token,
                signing_key=self.config.signing_key,
                expected=current,
            )

    def authenticate_for_refresh(
        self, token: str
    ) -> DesktopTokenClaims | None:
        """与 ``authenticate`` 相同但跳过 ``exp`` 校验。

        桌面端长时间不动导致系统休眠后 token 过期，但仍可用结构完整
        的过期 token 换新而不走完整 SSO 重登——SSO 会话可能仍有效，
        ``refresh()`` 的 ``_claims_match_current_locked`` 才是真正
        的安全防线。
        """
        with self._lock:
            current = self._current
            if current is None:
                return None
            return decode_desktop_token(
                token,
                signing_key=self.config.signing_key,
                expected=current,
                skip_expiry=True,
            )

    def authenticate_preview_session_token(
        self, token: str
    ) -> DesktopTokenClaims | None:
        """只接受同一 current session 的 preview capability。"""
        with self._lock:
            current = self._current
            if current is None:
                return None
            return decode_desktop_preview_session_token(
                token,
                signing_key=self.config.signing_key,
                expected=current,
            )

    def issue_preview_ticket(
        self,
        claims: DesktopTokenClaims,
        filepath: str,
    ) -> str:
        """仅由已认证的 current desktop session 派生文件预览票据。"""
        with self._lock:
            if not self._claims_match_current_locked(claims):
                raise DesktopHandoffUnauthorized("session_stale")
            current = self._current
            assert current is not None
            return create_desktop_preview_ticket(
                current,
                filepath=filepath,
                signing_key=self.config.signing_key,
            )

    def authenticate_preview_ticket(self, ticket: str, filepath: str) -> bool:
        """只验证当前会话签发且精确绑定同一路径的预览票据。"""
        with self._lock:
            current = self._current
            if current is None:
                return False
            return decode_desktop_preview_ticket(
                ticket,
                filepath=filepath,
                signing_key=self.config.signing_key,
                expected=current,
            )

    def _claims_match_current_locked(
        self,
        claims: DesktopTokenClaims,
    ) -> bool:
        current = self._current
        return bool(
            current is not None
            and claims.user_id == current.user_id
            and claims.session_id == current.session_id
            and claims.operation_id == current.operation_id
            and claims.audience == current.audience
            and claims.generation == current.generation
            and claims.slot_generation == current.slot_generation
            and claims.profile_namespace == current.profile_namespace
            and claims.purpose == current.purpose
        )

    def refresh(self, claims: DesktopTokenClaims) -> DesktopRedeemResult:
        """在状态锁内重检 current binding 后签发同会话 Token。"""
        with self._lock:
            if not self._claims_match_current_locked(claims):
                raise DesktopHandoffUnauthorized("session_stale")
            current = self._current
            assert current is not None
            try:
                token = self._token_factory(
                    current.user_id,
                    signing_key=self.config.signing_key,
                    session_id=current.session_id,
                    operation_id=current.operation_id,
                    audience=current.audience,
                    generation=current.generation,
                    slot_generation=current.slot_generation,
                    profile_namespace=current.profile_namespace,
                    purpose=current.purpose,
                    expires_seconds=_DESKTOP_SESSION_TTL_SECONDS,
                )
            except Exception as exc:
                raise DesktopTokenSigningError(
                    "token_signing_failed"
                ) from exc
            preview_token = create_desktop_preview_session_token(
                current,
                signing_key=self.config.signing_key,
            )
            return DesktopRedeemResult(
                token,
                preview_token,
                _DESKTOP_SESSION_TTL_SECONDS,
                current,
            )

    def issue_milestone_proof(
        self,
        claims: DesktopTokenClaims,
        milestone: str,
    ) -> str:
        """锁内重检 current session 后生成短效 proof。"""
        with self._lock:
            if not self._claims_match_current_locked(claims):
                raise DesktopHandoffUnauthorized("session_stale")
            current = self._current
            assert current is not None
            return create_milestone_proof(
                current,
                milestone=milestone,
                handshake_secret=self.config.handshake_secret,
            )


_STATE_LOCK = threading.Lock()
_STATE_FINGERPRINT: DesktopSlotSecurityConfig | None = None
_STATE: DesktopSecurityState | None = None


def get_desktop_security_state() -> DesktopSecurityState | None:
    """返回当前进程唯一的 v2 安全状态。"""
    global _STATE_FINGERPRINT, _STATE
    config = DesktopSlotSecurityConfig.from_env()
    with _STATE_LOCK:
        if config is None:
            _STATE_FINGERPRINT = None
            _STATE = None
            return None
        if _STATE is None or _STATE_FINGERPRINT != config:
            _STATE_FINGERPRINT = config
            _STATE = DesktopSecurityState(config)
        return _STATE


def reset_desktop_security_state() -> None:
    """测试或进程重配时丢弃内存态；不会持久化任何凭证。"""
    global _STATE_FINGERPRINT, _STATE
    with _STATE_LOCK:
        _STATE_FINGERPRINT = None
        _STATE = None
